#!name=腾讯新闻
#!desc=fmz200/wool_scripts · 某些APP要清除缓存或者重新安装拦截广告才会生效！
#!author=奶思

[MITM]
hostname = r.inews.qq.com, news.ssp.qq.com

[Rewrite]
request if ${url} ~= /^https?:\/\/r\.inews\.qq\.com\/(adsBlacklist|getFullScreenPic|getQQNewsRemoteConfig)/i then reject(404)
request if ${url} ~= /^https?:\/\/r\.inews\.qq\.com\/(getBannerAds|getNewsRemoteConfig|getSplash|searchHotCatList|upLoadLoc)/i then reject(404)

[Script]
response if ${url} ~= /^https?:\/\/(news\.ssp\.qq\.com\/app|r\.inews\.qq\.com\/(get(QQNewsUnreadList|TagFeedList)|gw\/page\/event_detail|news_feed\/hot_module_list))/i then script("https://raw.githubusercontent.com/app2smile/rules/master/js/qq-news.js") with enable=${tgxyxbwf_enable}, tag="腾讯新闻", timeout=60, requires_body=true
